css:
.burst-meteor {
  position: absolute;
  top: 50%;
  left: 50%;
  width: var(--len);
  height: var(--thick);
  border-radius: 999px;
  background: linear-gradient(
    to right,
    transparent 0%,
    hsla(var(--hue), 100%, 60%, 0.02) 8%,
    hsla(var(--hue), 100%, 70%, 0.15) 25%,
    hsla(var(--hue), 100%, 78%, 0.45) 50%,
    hsla(var(--hue), 100%, 85%, 0.8) 75%,
    hsla(var(--hue), 100%, 92%, 0.98) 92%,
    hsla(var(--hue), 100%, 98%, 1) 100%
  );
  transform-origin: 100% 50%;
  opacity: 0;
  will-change: transform, opacity;
  filter:
    drop-shadow(0 0 3px hsla(var(--hue), 100%, 85%, 0.9))
    drop-shadow(0 0 6px hsla(var(--hue), 100%, 70%, 0.5))
    drop-shadow(0 0 12px hsla(var(--hue), 100%, 60%, 0.25));
  animation: meteorConverge var(--duration) cubic-bezier(0.2, 0.5, 0.4, 1) var(--delay) forwards;
}

@keyframes meteorConverge {
  0% {
    opacity: 0;
    transform:
      translate(calc(sign(var(--start-x)) * var(--travel)), var(--y-pos))
      rotate(calc(90deg + sign(var(--start-x)) * 90deg - sign(var(--start-x)) * var(--angle)))
      scaleX(0.05);
  }
  6% {
    opacity: 1;
    transform:
      translate(calc(sign(var(--start-x)) * var(--travel) * 0.88), var(--y-pos))
      rotate(calc(90deg + sign(var(--start-x)) * 90deg - sign(var(--start-x)) * var(--angle)))
      scaleX(0.3);
  }
  35% {
    opacity: 1;
    transform:
      translate(calc(sign(var(--start-x)) * var(--travel) * 0.35), var(--y-pos))
      rotate(calc(90deg + sign(var(--start-x)) * 90deg - sign(var(--start-x)) * var(--angle)))
      scaleX(1);
  }
  55% {
    opacity: 0.9;
    transform:
      translate(calc(sign(var(--start-x)) * var(--travel) * 0.05), var(--y-pos))
      rotate(calc(90deg + sign(var(--start-x)) * 90deg - sign(var(--start-x)) * var(--angle)))
      scaleX(0.85);
  }
  75% {
    opacity: 0.5;
    transform:
      translate(calc(sign(var(--start-x)) * var(--travel) * -0.1), var(--y-pos))
      rotate(calc(90deg + sign(var(--start-x)) * 90deg - sign(var(--start-x)) * var(--angle)))
      scaleX(0.4);
  }
  100% {
    opacity: 0;
    transform:
      translate(calc(sign(var(--start-x)) * var(--travel) * -0.18), var(--y-pos))
      rotate(calc(90deg + sign(var(--start-x)) * 90deg - sign(var(--start-x)) * var(--angle)))
      scaleX(0.08);
  }
}
